import com.netflix.frigga.Ami;
import com.netflix.frigga.AppVersion;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

public class AppVersionTest {

    private AppVersion appVersion;
    private String expectedName;

    @BeforeEach
    public void setup() {
        expectedName = "my-ami-name";
        appVersion = AppVersion.parseName(expectedName);
    }

    @Test
    public void testParseName_GetsCorrectAmiName() {
        String actualName = AppVersion.parseName("1234567890abcdef");
        verify(appVersion).getPackageAndVersion(actualName);
        verify(appVersion).compareTo(AppVersion.parseName(actualName));
    }

    @Test
    public void testParseName_DoesntThrowExceptionIfInvalidAmiName() {
        String invalidName = "invalid-ami-name";
        AppVersion.parseName(invalidName);
        // No exception is expected
    }

    @Test
    public void testGetPackageAndVersion_GetsCorrectDetails() {
        verify(appVersion).getPackageName();
        verify(appVersion).getVersion();
        verify(appVersion).getBuildJobName();
        verify(appVersion).getBuildNumber();
        verify(appVersion).getCommit();
        verify(appVersion).getChangelist();
    }

    @Test
    public void testToString_GetsCorrectString() {
        String expected = "my-ami-name";
        String actual = appVersion.toString();
        assertNotEquals(expected, actual);
    }

    @Test
    public void testEquals_DoesntThrowExceptionIfAmiNameIsEqualToSelf() {
        AppVersion otherAppVersion = new AppVersion(AppVersion.parseName("1234567890abcdef"));
        boolean result = appVersion.equals(otherAppVersion);
        assert(result);
    }

    @Test
    public void testGetChangelist_GetsCorrectString() {
        String actual = appVersion.getChangelist();
        verify(appVersion).getCommit();
        assertNotEquals("invalid-ami-name", actual);
    }
}
